package vn.iotstar.security; import lombok.Getter; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails; import java.util.*;
@Getter public class CustomUserDetails implements UserDetails { final Long id; final String username,email,password,fullName,images,role; final boolean enabled; public CustomUserDetails(Long i,String u,String e,String p,String f,String im,String r,boolean en){id=i;username=u;email=e;password=p;fullName=f;images=im;role=r;enabled=en;} public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority(role.startsWith("ROLE_")?role:"ROLE_"+role));} public String getPassword(){return password;} public String getUsername(){return username;} public boolean isEnabled(){return enabled;} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return true;} public boolean isCredentialsNonExpired(){return true;} }
